  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In humans, lorlatinib showed an average CSF/free plasma concentration ratio of 0.75, indicating high CNS permeability after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Peripheral i.v. administration of a cofactor elevated BH4 in CSF within 90 minutes, demonstrating direct systemic-to-CSF access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "CZC25146 showed negligible brain penetration in mice, with a total brain/plasma AUC ratio reported as 'Negi', arguing against meaningful CNS access for that molecule.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple direct systemic CNS-exposure records—human CSF/plasma ratios, PET imaging, and CSF elevation after i.v. dosing—support meaningful CNS access; the single mouse negative is outweighed by the strong positive evidence.",
  "evidence_gaps": [
    "The single negative record (C20) lacks a numeric AUC ratio, limiting quantitative comparison.",
    "Some positive records rely on qualitative or single-timepoint CSF measurements rather than full pharmacokinetic profiles."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

